
import { useEffect, useState } from "react";
import { SessionEventsRegistry, type ImageData } from "biosensesignal-react-native-sdk";


export const useImages = () => {
    const [imageData, setImageData] = useState<ImageData>();

    useEffect(() => {
        const listener = SessionEventsRegistry.registerImages(
            (imageData: ImageData) => setImageData(imageData)
        );

        return () => {
            listener.remove();
        };
    }, []);

    return imageData;
}