import type { VitalSignConfidence } from '../VitalSignConfidence';
import { VitalSignTypes } from "../VitalSignTypes";
import type { RRI } from "./RRI";
import { VitalSignBase } from "./VitalSignBase";

export class VitalSignRRI extends VitalSignBase<RRI[]> {
        
    readonly confidence: VitalSignConfidence | null;

    constructor(value: RRI[], confidence: VitalSignConfidence | null = null) {
        super(VitalSignTypes.RRI, value);
        this.confidence = confidence;
    }
}