
import { useEffect, useState } from "react";
import { SessionEventsRegistry, type WarningData } from "biosensesignal-react-native-sdk";

export const useSessionWarnings = () => {
    const [warning, setWarning] = useState<WarningData>();

    useEffect(() => {
        const listener = SessionEventsRegistry.registerWarnings(
            (warning: WarningData) => setWarning(warning),
        );

        return () => {
            listener.remove();
        };
    }, []);

    return warning;
}