import { BridgeEvents, BridgeModelFactory, BridgeVitalSignsFactory } from "./bridge";
import type { ImageData } from "./images";
import { NativeModules, Platform, NativeEventEmitter, EmitterSubscription } from "react-native";
import type { VitalSign, VitalSignsResults } from "./vital-signs";
import type { LicenseInfo, SessionEnabledVitalSigns, SessionState } from "./session-info";
import type { ErrorData, WarningData } from "./alerts";
import { PPGDeviceInfo, PPGDeviceBatteryLevel } from "./ppg_device";
import { FallDetectionData } from "./fall_detection/FallDetectionData";


const emitter = new NativeEventEmitter(
    Platform.OS == 'ios' ? NativeModules.BiosenseSignalEventEmitter : null
);

export type EventRegistryListener = {
    remove: () => void
}

export const SessionEventsRegistry = {

    registerImages: (onImageData: (imageData: ImageData) => void): EventRegistryListener => {
        const listener: EmitterSubscription = emitter.addListener(BridgeEvents.imageData, (data: object) => {
            onImageData(BridgeModelFactory.createImageData(data))
        });

        return {
            remove: () => listener.remove()
        };
    },

    registerVitalSigns: (onVitalSign: (vitalSign: VitalSign) => void): EventRegistryListener => {
        const listener = emitter.addListener(BridgeEvents.sessionVitalSign, (data: object) => {
            const vitalSign = BridgeVitalSignsFactory.createVitalSign(data);
            if (vitalSign) {
                onVitalSign(vitalSign);
            }
        });

        return {
            remove: () => {
                listener.remove();
            }
        };
    },

    registerFinalResults: (onFinalResults: (finalResults: VitalSignsResults) => void): EventRegistryListener => {
        const listener = emitter.addListener(BridgeEvents.sessionFinalResults, (data: object) => {
            onFinalResults(BridgeVitalSignsFactory.createFinalResults(data));
        });

        return {
            remove: () => {
                listener.remove();
            }
        }
    },

    registerWarnings: (onWarning: (warning: WarningData) => void): EventRegistryListener => {
        const listener = emitter.addListener(BridgeEvents.sessionWarning, (data: object) => {
            onWarning(BridgeModelFactory.createWarningData(data));
        });

        return {
            remove: () => {
                listener.remove();
            }
        };
    },

    registerErrors: (onError: (error: ErrorData) => void): EventRegistryListener => {
        const listener = emitter.addListener(BridgeEvents.sessionError, (data: object) => {
            onError(BridgeModelFactory.createErrorData(data));
        });

        return {
            remove: () => {
                listener.remove();
            }
        };
    },

    registerSessionState: (onSessionState: (state: SessionState) => void): EventRegistryListener => {
        const listener = emitter.addListener(BridgeEvents.sessionStateChange, (data: number) => {
            onSessionState(BridgeModelFactory.createSessionState(data));
        });

        return {
            remove: () => {
                listener.remove();
            }
        };
    },

    registerLicenseInfo: (onSessionState: (licenseInfo: LicenseInfo) => void): EventRegistryListener => {
        const listener = emitter.addListener(BridgeEvents.licenseInfo, (data: object) => {
            onSessionState(BridgeModelFactory.createLicenseInfo(data));
        });

        return {
            remove: () => {
                listener.remove();
            }
        };
    },

    registerEnabledVitalSigns: (onEnabledVitalSigns: (enabledVitalSigns: SessionEnabledVitalSigns) => void): EventRegistryListener => {
        const listener = emitter.addListener(BridgeEvents.enabledVitalSigns, (data: object) => {
            onEnabledVitalSigns(BridgeModelFactory.createEnabledVitalSigns(data));
        });

        return {
            remove: () => {
                listener.remove();
            }
        };
    },

    registerPPGDeviceInfo: (onPPGDeviceInfo: (ppgDeviceInfo: PPGDeviceInfo) => void): EventRegistryListener => {
        const listener = emitter.addListener(BridgeEvents.ppgDeviceInfo, (data: object) => {
            onPPGDeviceInfo(BridgeModelFactory.createPPGDeviceInfo(data));
        });

        return {
            remove: () => {
                listener.remove();
            }
        };
    },

    registerPPGDeviceBatteryLevel: (onPPGDeviceBatteryLevel: (batteryLevel: PPGDeviceBatteryLevel) => void): EventRegistryListener => {
        const listener = emitter.addListener(BridgeEvents.ppgDeviceBatteryLevel, (data: object) => {
            onPPGDeviceBatteryLevel(BridgeModelFactory.createPPGDeviceBatteryLevel(data));
        });

        return {
            remove: () => {
                listener.remove();
            }
        };
    },

    registerFallDetection: (onFallDetection: (fallDetectionData: FallDetectionData) => void): EventRegistryListener => {
        const listener: EmitterSubscription = emitter.addListener(BridgeEvents.fallDetectionData, (data: object) => {
            onFallDetection(BridgeModelFactory.createFallDetectionData(data))
        });

        return {
            remove: () => listener.remove()
        };
    },
    
}