import { VitalSign } from "./vitals/VitalSign";

export class VitalSignsResults {

    readonly results: Map<number, VitalSign> = new Map();

    constructor(results: VitalSign[]) {
        results.forEach(vitalSign => {
            this.results.set(vitalSign.type, vitalSign);
        });
    }
    
    public getResult(vitalSignType: number): VitalSign | undefined {
        return this.results.get(vitalSignType);
    }
}