
import { useEffect, useState } from "react";
import { SessionEventsRegistry, type FallDetectionData } from "biosensesignal-react-native-sdk";


export const useFallDetection = () => {
    const [fallDetectionData, setFallDetection] = useState<FallDetectionData>();

    useEffect(() => {
        const listener = SessionEventsRegistry.registerFallDetection(
            (fallDetectionData: FallDetectionData) => setFallDetection(fallDetectionData)
        );

        return () => {
            listener.remove();
        };
    }, []);

    return fallDetectionData;
}