import { NativeEventEmitter, NativeModules, Platform } from "react-native";
import uuid from 'react-native-uuid';
import { BridgeEvents, BridgeModelFactory } from "../bridge";
import { PPGDevice } from "./PPGDevice";
import { PPGDeviceType } from "./PPGDeviceType";
import { EmitterSubscription } from "react-native";
import { HealthMonitorException } from "..";


const BiosenseSignalReactNativeSDK = NativeModules.BiosenseSignalReactNativeSDK

const emitter = new NativeEventEmitter(
    Platform.OS == 'ios' ? NativeModules.BiosenseSignalEventEmitter : null
);

export class PPGDeviceScanner {

    private deviceType: PPGDeviceType;
    private scannerId;
    private onPPGDeviceDiscovered?: EmitterSubscription
    private onPPGDeviceScanFinished?: EmitterSubscription

    constructor(ppgDeviceType: PPGDeviceType) {
        this.deviceType = ppgDeviceType;
        this.scannerId = uuid.v4()
    }

    public async start(
        timeout: number | undefined, 
        onPPGDeviceDiscovered: (ppgDevice: PPGDevice) => void,
        onPPGDeviceScanFinished: () => void
    ) {
        if (this.onPPGDeviceDiscovered) {
            this.onPPGDeviceDiscovered.remove();
        }

        if (this.onPPGDeviceScanFinished) {
            this.onPPGDeviceScanFinished.remove();
        }


        this.onPPGDeviceDiscovered = emitter.addListener(BridgeEvents.ppgDeviceDiscovered, (data: object) => {
            const scanResult = data as {
                scannerId: string,
                device: object
            }
    
            if (scanResult.scannerId == this.scannerId) {
                onPPGDeviceDiscovered(BridgeModelFactory.createPPGDevice(scanResult.device));
            }
        });

        this.onPPGDeviceScanFinished = emitter.addListener(BridgeEvents.ppgDeviceScanFinished, (data: object) => {
            const result = data as {
                scannerId: string
            }
            
            if (result.scannerId == this.scannerId) {
                onPPGDeviceScanFinished();
            }
        });
        
        try {
            await BiosenseSignalReactNativeSDK.startPPGDevicesScan(this.scannerId, this.deviceType, timeout ?? 0);
        } catch (error: any) {
            throw new HealthMonitorException(error.message, parseInt(error.code))
        }
    }

    public async stop() {
        await BiosenseSignalReactNativeSDK.stopPPGDevicesScan(this.scannerId);
    }
}