import { NativeModules } from "react-native";
import { HealthMonitorException } from "../alerts";
import { PPGDeviceType } from "../ppg_device/PPGDeviceType";
import type { FaceSessionParameters } from "./FaceSessionParameters";
import type { LicenseDetails } from "./LicenseDetails";
import { MeasurementMode } from "./MeasurementMode";
import { PPGDeviceSessionParameters } from "./PPGDeviceSessionParameters";
import { Session } from "./Session";


const BiosenseSignalReactNativeSDK = NativeModules.BiosenseSignalReactNativeSDK

export const SessionBuilder = {
    faceSession: async (licenseDetails: LicenseDetails, parameters?: FaceSessionParameters, options?: Record<string, any>): Promise<Session> => {
        try {
            const session = new Session();
            await BiosenseSignalReactNativeSDK.createSession({
                measurementMode: MeasurementMode.FACE,
                cameraLocation: parameters?.cameraLocation,
                licenseKey: licenseDetails.licenseKey,
                productId: licenseDetails.productId === "" ? null : licenseDetails.productId, 
                subjectSex: parameters?.userInformation?.sex ?? parameters?.subjectDemographic?.sex,
                subjectAge: parameters?.userInformation?.age ?? parameters?.subjectDemographic?.age,
                subjectWeight: parameters?.userInformation?.weight ?? parameters?.subjectDemographic?.weight,
                subjectHeight:parameters?.userInformation?.height ??  parameters?.subjectDemographic?.height,
                subjectSmokingStatus: parameters?.userInformation?.smokingStatus,
                deviceOrientation: parameters?.deviceOrientation,
                imageFormatMode: parameters?.imageFormatMode,
                detectionAlwaysOn: parameters?.detectionAlwaysOn,
                strictMeasurementGuidance: parameters?.strictMeasurementGuidance,
                sdkAnalytics: parameters?.sdkAnalytics,
                options: options
            });

            return session;
        } catch (error: any) {
            throw new HealthMonitorException(error.message, parseInt(error.code))
        }
    },
    
    polarSession: async (
        licenseDetails: LicenseDetails, 
        parameters: PPGDeviceSessionParameters, 
        options?: Record<string, any>
    ): Promise<Session> => {
        try {
            const session = new Session();
            await BiosenseSignalReactNativeSDK.createPPGDeviceSession({
                licenseKey: licenseDetails.licenseKey,
                productId: licenseDetails.productId == "" ? null : licenseDetails.productId,
                deviceType: PPGDeviceType.POLAR,
                deviceId: parameters.deviceId,
                subjectSex: parameters?.userInformation?.sex ?? parameters?.subjectDemographic?.sex,
                subjectAge: parameters?.userInformation?.age ?? parameters?.subjectDemographic?.age,
                subjectWeight: parameters?.userInformation?.weight ?? parameters?.subjectDemographic?.weight,
                subjectHeight:parameters?.userInformation?.height ??  parameters?.subjectDemographic?.height,
                subjectSmokingStatus: parameters?.userInformation?.smokingStatus,
                fallDetection: parameters?.fallDetection,
                sdkAnalytics: parameters?.sdkAnalytics,
                options: options
            });

            return session;
        } catch (error: any) {
            throw new HealthMonitorException(error.message, parseInt(error.code))
        }
    }
}