
import { useEffect, useState } from "react";
import { SessionEventsRegistry, type VitalSign } from "biosensesignal-react-native-sdk";


export const useVitalSigns = () => {
    const [vitalSign, setVitalSign] = useState<VitalSign>();

    useEffect(() => {
        const listener = SessionEventsRegistry.registerVitalSigns(
            (vitalSign: VitalSign) => setVitalSign(vitalSign)
        );

        return () => {
            listener.remove();
        }
    }, []);

    return vitalSign;
}