
import { useEffect, useState } from "react";
import { SessionEventsRegistry, type SessionState } from "biosensesignal-react-native-sdk";

export const useSessionState = () => {
    const [sessionState, setSessionState] = useState<SessionState>();

    useEffect(() => {
        const listener = SessionEventsRegistry.registerSessionState(
            (state: SessionState) => setSessionState(state)
        );

        return () => {
            listener.remove();
        };
    }, []);

    return sessionState;
}