import { PPGDeviceBatteryLevel, PPGDeviceInfo } from "../ppg_device";
import { useState, useEffect } from "react"
import { SessionEventsRegistry } from "../";


export const usePPPDeviceInfo = () => {

    const [deviceInfo, setDeviceInfo] = useState<PPGDeviceInfo>();
    const [batteryLevel, setBatteryLevel] = useState<PPGDeviceBatteryLevel>();

    useEffect(() => {
        const infoListener = SessionEventsRegistry.registerPPGDeviceInfo(
            (deviceInfo: PPGDeviceInfo) => setDeviceInfo(deviceInfo)
        );

        const batteryListener = SessionEventsRegistry.registerPPGDeviceBatteryLevel(
            (batteryLevel: PPGDeviceBatteryLevel) => setBatteryLevel(batteryLevel)
        );

        return () => {
            infoListener.remove();
            batteryListener.remove();
        };
    }, []);

    return {
        deviceInfo,
        batteryLevel
    }


}