const vitalSignsResolver: Record<string, (value: object, confidence: VitalSignConfidence | null) => void> = {};
vitalSignsResolver[VitalSignTypes.PULSE_RATE] = (value: object, confidence: VitalSignConfidence | null) => new VitalSignPulseRate(Number(value), confidence);
vitalSignsResolver[VitalSignTypes.RESPIRATION_RATE] = (value: object, confidence: VitalSignConfidence | null) => new VitalSignRespirationRate(Number(value), confidence);
vitalSignsResolver[VitalSignTypes.OXYGEN_SATURATION] = (value: object) => new VitalSignOxygenSaturation(Number(value));
vitalSignsResolver[VitalSignTypes.SDNN] = (value: object, confidence: VitalSignConfidence | null) => new VitalSignSDNN(Number(value), confidence);
vitalSignsResolver[VitalSignTypes.STRESS_LEVEL] = (value: object) => new VitalSignStressLevel(Number(value));
vitalSignsResolver[VitalSignTypes.RRI] = (value: object, confidence: VitalSignConfidence | null) => {
    const rriArray: RRI[] = (value as object[]).map((obj: object) => obj as RRI);
    return new VitalSignRRI(rriArray, confidence);
};
vitalSignsResolver[VitalSignTypes.BLOOD_PRESSURE] = (value: object) => new VitalSignBloodPressure(value as BloodPressure);
vitalSignsResolver[VitalSignTypes.STRESS_INDEX] = (value: object) => new VitalSignStressIndex(Number(value));
vitalSignsResolver[VitalSignTypes.MEAN_RRI] = (value: object, confidence: VitalSignConfidence | null) => new VitalSignMeanRRI(Number(value), confidence);
vitalSignsResolver[VitalSignTypes.RMSSD] = (value: object) => new VitalSignRMSSD(Number(value));
vitalSignsResolver[VitalSignTypes.SD1] = (value: object) => new VitalSignSD1(Number(value));
vitalSignsResolver[VitalSignTypes.SD2] = (value: object) => new VitalSignSD2(Number(value));
vitalSignsResolver[VitalSignTypes.PRQ] = (value: object, confidence: VitalSignConfidence | null) => new VitalSignPRQ(Number(value), confidence);
vitalSignsResolver[VitalSignTypes.PNS_INDEX] = (value: object) => new VitalSignPNSIndex(Number(value));
vitalSignsResolver[VitalSignTypes.PNS_ZONE] = (value: object) => new VitalSignPNSZone(Number(value));
vitalSignsResolver[VitalSignTypes.SNS_INDEX] = (value: object) => new VitalSignSNSIndex(Number(value));
vitalSignsResolver[VitalSignTypes.SNS_ZONE] = (value: object) => new VitalSignSNSZone(Number(value));
vitalSignsResolver[VitalSignTypes.WELLNESS_INDEX] = (value: object) => new VitalSignWellnessIndex(Number(value));
vitalSignsResolver[VitalSignTypes.WELLNESS_LEVEL] = (value: object) => new VitalSignWellnessLevel(Number(value));
vitalSignsResolver[VitalSignTypes.LFHF] = (value: object) => new VitalSignLFHF(Number(value));
vitalSignsResolver[VitalSignTypes.HEMOGLOBIN] = (value: object) => new VitalSignHemoglobin(Number(value));
vitalSignsResolver[VitalSignTypes.HEMOGLOBIN_A1C] = (value: object) => new VitalSignHemoglobinA1C(Number(value));
vitalSignsResolver[VitalSignTypes.HIGH_HEMOGLOBIN_A1C_RISK] = (value: object) => new VitalSignHighHemoglobinA1CRisk(Number(value));
vitalSignsResolver[VitalSignTypes.HIGH_BLOOD_PRESSURE_RISK] = (value: object) => new VitalSignHighBloodPressureRisk(Number(value));
vitalSignsResolver[VitalSignTypes.ASCVD_RISK] = (value: object) => new VitalSignAscvdRisk(Number(value));
vitalSignsResolver[VitalSignTypes.NORMALIZED_STRESS_INDEX] = (value: object) => new VitalSignNormalizedStressIndex(Number(value));
vitalSignsResolver[VitalSignTypes.HEART_AGE] = (value: object) => new VitalSignHeartAge(Number(value));
vitalSignsResolver[VitalSignTypes.LOW_HEMOGLOBIN_RISK] = (value: object) => new VitalSignLowHemoglobinRisk(Number(value));
vitalSignsResolver[VitalSignTypes.HIGH_FASTING_GLUCOSE_RISK] = (value: object) => new VitalSignHighFastingGlucoseRisk(Number(value));
vitalSignsResolver[VitalSignTypes.HIGH_TOTAL_CHOLESTEROL_RISK] = (value: object) => new VitalSignHighTotalCholesterolRisk(Number(value));


export const BridgeVitalSignsFactory = {
    createVitalSign: (vitalSign: object): VitalSign | null => {
        const vitalSignInfo = vitalSign as {
            type: number,
            value: object,
            confidence: object | null
        };

        const confidenceInfo = vitalSignInfo.confidence as {
            level: number
        }

        var confidence: VitalSignConfidence | null = null;
        if (confidenceInfo) {
            confidence = {
                level: confidenceInfo.level
            }
        }
    
        return vitalSignsResolver[vitalSignInfo.type]?.(vitalSignInfo.value, confidence) ?? null;
    },

    createFinalResults(results: object): VitalSignsResults {
        const vitalSigns = (results as object[])
            .map((vitalSign) => this.createVitalSign(vitalSign))
            .filter((vitalSign) => vitalSign != null) as VitalSign[];
        console.log('vitalSigns', vitalSigns);
        return new VitalSignsResults(vitalSigns);
    }
}