import { HealthMonitorException } from "../alerts";
import type { SessionState } from "../session-info/SessionState";
import { NativeModules } from "react-native";

const BiosenseSignalReactNativeSDK = NativeModules.BiosenseSignalReactNativeSDK

export class Session {
    
    public async start(measurementDuration: number) {
        try {
            await BiosenseSignalReactNativeSDK.start(measurementDuration);
        } catch (error: any) {
            throw new HealthMonitorException(error.message, parseInt(error.code))
        }
    }

    public async stop() {
        try {
            await BiosenseSignalReactNativeSDK.stop();
        } catch (error: any) {
            throw new HealthMonitorException(error.message, parseInt(error.code))
        }
    }

    public async terminate() {
        await BiosenseSignalReactNativeSDK.terminate();
    }

    public getSessionState(): SessionState {
        return BiosenseSignalReactNativeSDK.getSessionState();
    }
}



