
import { useEffect, useState } from "react";
import { SessionEventsRegistry, type ErrorData } from "biosensesignal-react-native-sdk";

export const useSessionErrors= () => {
    const [error, setError] = useState<ErrorData>();

    useEffect(() => {
        const listener = SessionEventsRegistry.registerErrors(
            (error: ErrorData) => setError(error)
        );

        return () => {
            listener.remove();
        };
    }, []);

    return error;
}