
import { useEffect, useState } from "react";
import { SessionEventsRegistry, type VitalSignsResults } from "biosensesignal-react-native-sdk";


export const useFinalResults = () => {
    const [finalResults, setFinalResults] = useState<VitalSignsResults>();

    useEffect(() => {
        const listener = SessionEventsRegistry.registerFinalResults(
            (finalResults: VitalSignsResults) => setFinalResults(finalResults)
        );

        return () => {
            listener.remove();
        }
    }, []);

    return finalResults;
}