import type { ErrorData, WarningData } from '../alerts';
import { type FallDetectionData } from '../fall_detection';
import type { DetectionRect, ImageData } from '../images';
import { PPGDevice, PPGDeviceBatteryLevel, PPGDeviceInfo } from '../ppg_device';
import { type LicenseInfo, type SessionState, EnabledVitalSigns, SessionEnabledVitalSigns } from '../session-info';

export const BridgeModelFactory = {

    createImageData: (data: object): ImageData => {
        const imageInfo = data as {
            width: number,
            height: number,
            roi?: object,
            validity: number
        };
        
        return {
            imageWidth: imageInfo.width,
            imageHeight: imageInfo.height,
            roi: imageInfo.roi as DetectionRect,
            imageValidity: imageInfo.validity
        };
    },

    createWarningData: (data: object): WarningData => {
        const warningInfo = data as {
            domain: string,
            code: number
        };

        return {
            domain: warningInfo.domain,
            code: warningInfo.code
        }
    },

    createErrorData: (data: object): ErrorData => {
        const errorInfo = data as {
            domain: string,
            code: number
        };

        return {
            domain: errorInfo.domain,
            code: errorInfo.code
        }
    },

    createSessionState: (data: number): SessionState => {
        return (data as SessionState)
    },

    createLicenseInfo: (data: object): LicenseInfo => {
        const licenseInfo = data as {
            activation_id: string,
            offline_measurements_total?: number,
            offline_measurements_remaining?: number,
            offline_measurements_end_timestamp?: number
        };

        if (licenseInfo.offline_measurements_total == null) {
            return {
                activationInfo: { activationId: licenseInfo.activation_id },
            };
        }

        return {
            activationInfo: { activationId: licenseInfo.activation_id },
            offlineMeasurements: {
                totalMeasurements: licenseInfo.offline_measurements_total,
                remainingMeasurements: licenseInfo.offline_measurements_remaining ?? 0,
                measurementEndTimestamp: licenseInfo.offline_measurements_end_timestamp ?? 0
            }
        }
    },

    createEnabledVitalSigns(data: object): SessionEnabledVitalSigns {

        const enabledVitalSignsInfo = data as {
            device_enabled: number,
            measurement_mode_enabled: number,
            license_enabled: number
        };

        return new SessionEnabledVitalSigns(
            new EnabledVitalSigns(enabledVitalSignsInfo.device_enabled),
            new EnabledVitalSigns(enabledVitalSignsInfo.measurement_mode_enabled),
            new EnabledVitalSigns(enabledVitalSignsInfo.license_enabled)
        );
    },

    createPPGDevice: (data: object): PPGDevice => {
        const ppgDevice = data as {
            deviceId: string
            deviceType: number
        };

        return {
            deviceId: ppgDevice.deviceId,
            deviceType: ppgDevice.deviceType
        };
    },

    createPPGDeviceInfo: (data: object): PPGDeviceInfo => {
        return data as {
            deviceType: number,
            deviceId: string,
            version: string
        };
    },

    createPPGDeviceBatteryLevel: (data: object): PPGDeviceBatteryLevel => {
        return data as {
            deviceId: string,
            batteryLevel: number
        };
    },

    createFallDetectionData: (data: object): FallDetectionData => {
        const fallDetectionData = data as {
            time: number
        }

        return {
            time: new Date(fallDetectionData.time)
        }
    }
}