

export class EnabledVitalSigns {

    private readonly enabledVitalSigns: number;

    constructor(enabledVitalSigns: number) {
        this.enabledVitalSigns = enabledVitalSigns;
    }

    public isEnabled(vitalSignType: number) {
        return (BigInt(this.enabledVitalSigns) & BigInt(vitalSignType)) > BigInt(0);
    }

}