
import { useEffect, useState } from "react";
import { SessionEventsRegistry, type SessionEnabledVitalSigns } from "biosensesignal-react-native-sdk";

export const useEnabledVitalSigns = () => {
    const [enableVitalSigns, setEnabledVitalSigns] = useState<SessionEnabledVitalSigns>();

    useEffect(() => {
        const listener = SessionEventsRegistry.registerEnabledVitalSigns(
            (enableVitalSigns: SessionEnabledVitalSigns) => setEnabledVitalSigns(enableVitalSigns)
        );

        return () => {
            listener.remove();
        };
    }, []);

    return enableVitalSigns;
}