import {  } from "../ppg_device";
import { useState, useRef, useEffect } from "react"
import { PPGDeviceScanner, PPGDevice, PPGDeviceType} from "../ppg_device";


export const usePPGDeviceScanner = (deviceType: PPGDeviceType) => {

    const [discoveredPPGDevice, setDiscoveredDevice] = useState<PPGDevice>();
    const [isScanning, setIsScanning] = useState<boolean>();
    const ppgScanner = useRef<PPGDeviceScanner>()

    useEffect(() => {
        ppgScanner.current = new PPGDeviceScanner(deviceType);
        return () => {
            ppgScanner.current?.stop()
        }
    }, []);
    
    const startScan = async (timeoutDuration?: number) => {
        await ppgScanner.current?.start(
            timeoutDuration,
            (ppgDevice: PPGDevice) => {
                setDiscoveredDevice(ppgDevice);
            },
            () => {
                setIsScanning(false)
            }
        )
        
        setIsScanning(true)
    }

    const stopScan = () => {
        ppgScanner.current?.stop();
        setIsScanning(false);
    }

    return {
        startScan,
        stopScan,
        isScanning,
        discoveredPPGDevice
    }


}