import { useEffect, useState } from "react";
import { SessionEventsRegistry, type LicenseInfo } from "biosensesignal-react-native-sdk";


export const useLicenseInfo = () => {
    const [licenseInfo, setLiceseInfo] = useState<LicenseInfo>();
    useEffect(() => {
        const listener = SessionEventsRegistry.registerLicenseInfo(
            (licenseInfo: LicenseInfo) => setLiceseInfo(licenseInfo)
        );

        return () => {
            listener.remove();
        }
    }, []);

    return licenseInfo;
}