import { EnabledVitalSigns } from "./EnabledVitalSigns";

export class SessionEnabledVitalSigns {

    readonly deviceEnabled: EnabledVitalSigns;
    readonly measurementModeEnabled: EnabledVitalSigns;
    readonly licenseEnabled: EnabledVitalSigns;

    constructor(deviceEnabled: EnabledVitalSigns, measurementModeEnabled: EnabledVitalSigns, licenseEnabled: EnabledVitalSigns) {
        this.deviceEnabled = deviceEnabled;
        this.measurementModeEnabled = measurementModeEnabled;
        this.licenseEnabled = licenseEnabled;
    }

    public isEnabled(vitalSignType: number): boolean {
        return this.deviceEnabled.isEnabled(vitalSignType) 
            && this.measurementModeEnabled.isEnabled(vitalSignType) 
            && this.licenseEnabled.isEnabled(vitalSignType);
    }
}